negativeExample:
class Example {
    void otherMethod(String s, int i) {
        // This should not be matched by the rule, as it uses .startsWith instead of .equals
        if (s.length() >= 5 && s.substring(i - 5, i).startsWith("test")) {
            System.out.println("Other condition");
        }
    }

    void safeMethod(String s, int i) {
        // Already safe, should not be matched
        if (s.length() >= 3 && i >= 3 && s.substring(i - 3, i).equals("foo")) {
            System.out.println("Already safe");
        }
    }

    void nonLiteralLen(String s, int i, int len) {
        // len is not a literal, should not be matched by a rule with isLiteral($len) guard
        if (s.length() >= len && s.substring(i - len, i).equals("abc")) {
            System.out.println("Non-literal length");
        }
    }

    void differentSubstringArgs(String s, int i) {
        // Different substring arguments, should not be matched
        if (s.length() >= 3 && s.substring(0, i).equals("def")) {
            System.out.println("Different substring args");
        }
    }
}
